    return out",
   "newText": "def transform(grid):
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    marker = next(v for v in counts if v != background)
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Join consecutive markers on each row and column, filling only the
    # intervening background cells with 2.
    for r in range(h):
        marks = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(marks, marks[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == background:
