{
 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL-openclaw-luna6-low-ws0/frozen/seen-4/play/users/u039/system/state/workspace/programs/task-b5a17c2e.py",
 "content": "def transform(grid):
    # Recolor the background cells lying between consecutive marker cells
    # in any row or column. Marker is the least frequent non-background color.
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = max(counts, key=counts.get)
    marker = min((v for v in counts if v != background), key=lambda v: counts[v])
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(h):
        marks = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(marks, marks[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 2
    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(marks, marks[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out
"
